function majorityOverlap(oldSet, newSet){
  const inter = oldSet.filter(s => newSet.includes(s)).length;
  const safe = inter > oldSet.length/2 && inter > newSet.length/2;
  return safe;
}
const changes = [
  { name: 'add-one',        old: ['a','b','c'],         next: ['a','b','c','d'] },
  { name: 'remove-one',     old: ['a','b','c','d','e'], next: ['a','b','c','d'] },
  { name: 'swap-two-atomic',old: ['a','b','c'],         next: ['a','d','e'] },
  { name: 'replace-all',    old: ['a','b','c'],         next: ['d','e','f'] }
];
for (const c of changes) {
  console.log(c.name + ': ' + (majorityOverlap(c.old, c.next) ? 'SAFE' : 'UNSAFE'));
}
